 padding: 0.35rem 1rem 0.25rem 1rem;
 font-size: 1rem;
}

.btn:hover {
 background-color: #ecf2fd;
}

.btn:active {
 background-color: #d1e0fe;
}

.btn:focus {
 outline: none;
 border: black solid 2px;
}

.btn-primary {
 color: white;
 background-color: black;
 width: 100%;
 padding: 0.75rem;
 font-size: 1.3rem;
 border: black solid 2px;
 margin: 1rem 0;
}

