 import ToDoItem from "./components/ToDoItem.vue";

 export default {
 name: "app",
 components: {
 ToDoItem,
 },
 data() {
 return {
 ToDoItems: [
 { id: `todo-${nanoid()}`, label: "Learn Vue", done: false },
 {
 id: `todo-${nanoid()}`,
 label: "Create a Vue project with the CLI",
 done: true,
 },
 { id: `todo-${nanoid()}`, label: "Have fun", done: true },
 {
 id: `todo-${nanoid()}`,
 label: "Create a to-do list",
 done: false,
 },
 ],
 };
 },
 };
 ```

3. Now, add the `v-for` directive and `key` attribute to the ` ` element in your `App.vue` template, like so:

 ```vue





